_S_RUN, _S_WAIT, _S_END = "run", "wait", "end"
# G phases.  "drive" while in a phase named below means "the position last
# yielded in that phase was rejected upstream -- produce the next one".
_G_SUB = "sub"        # (re)start / resume the sub-sequence enumerator
_G_EXT = "ext"        # the one-more-repetition child enumerator is open
_G_SETTLE = "settle"  # yielded the current repetition's end; shorten sub
_G_EMPTY = "empty"    # yielded one empty match; fall back to no repetition
_G_FINAL = "final"    # yielded "stop without another repetition"; done
# Lazy G phases: the minimum is offered before any expansion.
_G_LSTART = "lstart"      # fresh entry; offer the minimum first
_G_LSETTLED = "lsettled"  # minimum offered; expand on the next drive
_G_LSUB = "lsub"          # the sub-sequence enumerator is open
_G_LEXT = "lext"          # the one-more-repetition child enumerator is open
_G_LEMPTY = "lempty"      # yielded one empty match; nothing more to offer


class _Runner:
    def __init__(self, program, text: str) -> None:
        self.pieces, self.ngroups = program
        self.text = text
        self.n = len(text)
        self.caps: list = [None] * (self.ngroups + 1)

    def _snap(self):
        return list(self.caps)

    def _restore(self, snapshot) -> None:
        self.caps[:] = snapshot

    def _seq_frame(self, pieces, pos: int):
        # ["S", pieces, pos, records, phase, gframe]
        return ["S", pieces, pos, [], _S_RUN, None]

    def _group_frame(self, pieces, k: int, pos: int, count: int, entry,
                     mode: str):
        # ["G", pieces, k, base, count, phase, subf, extf,
        #  entry, repstate, sub_end, mode, yielded]
        phase = _G_LSTART if mode == "lazy" else _G_SUB
        return ["G", pieces, k, pos, count, phase, None, None,
                entry, entry, pos, mode, False]

    # -- S frame ------------------------------------------------------------

    def _s_backtrack(self, f):
        records = f[3]
        while records:
            if records[-1][0] == "G":
                gframe = records.pop()[1]
                f[5] = gframe
                f[4] = _S_WAIT
                return ("push", gframe)
            _, start, count, maxcount, mode = records.pop()
            pieces = f[1]
            j = len(records)
            lo = pieces[j][1]
            if mode == "lazy":
                # Grow towards the feasible maximum one character at a time.
                count += 1
                if count <= maxcount:
                    records.append(("A", start, count, maxcount, mode))
                    f[2] = start + count
                    f[4] = _S_RUN
                    return "again"
            elif mode == "greedy":
                count -= 1
                if count >= lo:
                    records.append(("A", start, count, maxcount, mode))
                    f[2] = start + count
                    f[4] = _S_RUN
                    return "again"
            # possessive: the count is committed and offers no alternative
        f[4] = _S_END
        return "fail"

    def _step_s(self, f, event):
        _, pieces, pos, records, phase, _gf = f
        if phase == _S_WAIT:
            if event[0] == "yield":
                records.append(("G", event[2]))
                f[2] = event[1]
                f[4] = _S_RUN
                f[5] = None
                return "again"
            return self._s_backtrack(f)
        if phase == _S_END:
            return self._s_backtrack(f)
        # _S_RUN
        while True:
            k = len(records)
            pos = f[2]
            if k == len(pieces):
                f[4] = _S_END
                return ("yield", pos)
            atom, lo, hi, mode = pieces[k]
            if atom[0] != "grp":
                start = pos
                count = 0
                while (
                    count < hi
                    and pos < self.n
                    and _atom_matches(atom, self.text[pos])
                ):
                    pos += 1
                    count += 1
                if count < lo:
                    return self._s_backtrack(f)
                maxcount = count
                if mode == "lazy":
                    # Start at the minimum; backtracking grows the run.
                    count = lo
                records.append(("A", start, count, maxcount, mode))
                f[2] = start + count
                continue
            f[4] = _S_WAIT
            f[5] = None
            entry = self._snap()
            return ("push",
                    self._group_frame(pieces, k, pos, 0, entry, mode))

    # -- G frame ------------------------------------------------------------

    def _step_g(self, f, event):
        mode = f[11]
        if mode == "lazy":
            return self._step_g_lazy(f, event)
        if mode == "possessive":
            # Greedy enumeration, but only its first (longest) offer is
            # ever presented: once yielded, the choice is committed and
            # the frame has no alternative.
            if event[0] == "drive" and f[12]:
                return "fail"
            action = self._step_g_greedy(f, event)
            if isinstance(action, tuple) and action[0] == "yield":
                f[12] = True
            return action
        return self._step_g_greedy(f, event)

    def _step_g_greedy(self, f, event):
        (_, pieces, k, base, count, phase, subf, extf,
         entry, repstate, sub_end) = f[:11]
        gid, sub = pieces[k][0][1]
        lo, hi = pieces[k][1], pieces[k][2]

        if event[0] == "drive":
            if phase == _G_SUB:
                # A suspended G frame never keeps phase == sub (it always
                # moves to ext/settle/empty before yielding), so reaching
                # here on "drive" is a fresh entry at repetition count 0.
                # With an upper bound of zero the group never participates.
                if count >= hi:
                    self._restore(entry)
                    f[5] = _G_FINAL
                    return ("yield", base)
                child = self._seq_frame(sub, base)
                f[6] = child
                return ("push", child)
            if phase == _G_EXT:
                return ("push", extf)
            if phase == _G_SETTLE:
                # Give up the currently offered repetition and ask sub for
                # a shorter match, restoring the state sub last produced.
                self._restore(repstate)
                f[5] = _G_SUB
                return ("push", subf)
            if phase == _G_EMPTY:
                # The empty match was rejected; stop without it, if allowed.
                self._restore(entry)
                if count >= lo:
                    f[5] = _G_FINAL
                    return ("yield", base)
                return "fail"
            return "fail"  # _G_FINAL: the settlement has no alternative
